window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[345]={"id":"345","numero":345,"titre":"Malaise grave du nourrisson, mort subite","objectifs":[{"id":"345-1","rang":"A","rubrique":"Définition","titre":"Mort inattendue du nourrisson : connaître la définition","contenu":"<p>La <span class=\"kw-def\">mort inattendue du nourrisson</span> (<span class=\"kw-def\">MIN</span>, <em>SUDI</em> en anglais) désigne une mort survenant brutalement chez un nourrisson de <span class=\"kw-chiffre\">&lt; 2 ans</span>, alors que <strong>rien dans ses <span class=\"kw-clinique\">antécédents connus</span></strong> ne pouvait la laisser prévoir. Il n'existe pas de code CIM dédié à la MIN.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th><th>Code CIM / repère</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">MIN</span> (mort inattendue)</td><td>Mort brutale et imprévisible chez un nourrisson <span class=\"kw-chiffre\">&lt; 2 ans</span>, sans antécédent annonciateur</td><td>Pas de code CIM dédié</td></tr>\n          <tr><td><span class=\"kw-def\">MSN</span> (mort subite, <em>SIDS</em>)</td><td><span class=\"kw-clinique\">Aucune cause directe</span> identifiée malgré des investigations exhaustives : enquête sur les lieux du décès, anamnèse, examen physique, <span class=\"kw-bio\">bilan paraclinique</span> <strong>et <span class=\"kw-clinique\">autopsie</span></strong> → <span class=\"kw-def\">diagnostic d'exclusion</span></td><td><span class=\"kw-chiffre\">Code CIM</span> existant chez les <span class=\"kw-chiffre\">&lt; 1 an</span></td></tr>\n          <tr><td><span class=\"kw-def\">MIN de cause indéterminée</span></td><td>Investigations post-mortem incomplètes</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-def\">MSN</span> représente environ <span class=\"kw-chiffre\">40 % des MIN</span> chez les nourrissons de <span class=\"kw-chiffre\">&lt; 1 an</span>.</p>\n      <div class=\"callout callout-info\"><strong>Tableau typique.</strong> Nourrisson âgé de <span class=\"kw-chiffre\">2-4 mois</span>, <span class=\"kw-clinique\">retrouvé mort dans son sommeil</span>.</div>","frequence":0},{"id":"345-2","rang":"A","rubrique":"Epidémiologie","titre":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","contenu":"<p>L'<span class=\"kw-def\">épidémiologie</span> distingue la MIN globale et la MSN (sous-groupe à code CIM, qui permet le suivi épidémiologique).</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Chiffres</th></tr></thead>\n        <tbody>\n          <tr><td>MIN chez les <span class=\"kw-chiffre\">&lt; 1 an</span></td><td><span class=\"kw-chiffre\">350 à 400 décès/an</span></td></tr>\n          <tr><td>MIN chez les <span class=\"kw-chiffre\">1-2 ans</span></td><td>environ <span class=\"kw-chiffre\">10× moins</span></td></tr>\n          <tr><td>MSN (incidence)</td><td><span class=\"kw-chiffre\">2-3/10 000</span> naissances vivantes, soit <span class=\"kw-chiffre\">~150 décès/an</span> en France</td></tr>\n          <tr><td>MSN / mortalité infantile</td><td>environ <span class=\"kw-chiffre\">6 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modèle du triple risque</strong> : décès d'un <span class=\"kw-etio\">enfant vulnérable</span> placé dans un <span class=\"kw-etio\">environnement de sommeil à risque</span> au cours d'une <span class=\"kw-etio\">période critique</span> de son développement.</p>\n      <p><strong>Facteurs de risque de MSN</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td>Antécédents personnels</td><td><span class=\"kw-etio\">Prématurité</span> ; RCIU ; <span class=\"kw-etio\">tabagisme anténatal</span> ; sexe masculin</td></tr>\n          <tr><td>Période la plus à risque</td><td><span class=\"kw-chiffre\">Âge &lt; 6 mois</span> ; <span class=\"kw-etio\">hiver</span></td></tr>\n          <tr><td>Circonstances / environnement</td><td><span class=\"kw-alerte\">Couchage en décubitus ventral</span> ; enfouissement du visage dans la literie ; hyperflexion cervicale ; <span class=\"kw-etio\">tabagisme parental</span> ; lieu surchauffé / enfant trop couvert ; <span class=\"kw-etio\">co-sleeping</span> ; nourrisson isolé seul dans une chambre</td></tr>\n          <tr><td>Contexte social</td><td><span class=\"kw-etio\">Mère jeune</span> ; grossesse non suivie ; milieu défavorisé</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À jour du référentiel.</strong> L'<span class=\"kw-etio\">allaitement artificiel</span> a été <strong>retiré</strong> de la liste des facteurs de risque.</div>","frequence":0},{"id":"345-3","rang":"A","rubrique":"Étiologies","titre":"Mort inattendue du nourrisson : connaître les aspects étiologiques (causes fréquentes)","contenu":"<p>Les <span class=\"kw-etio\">causes de MIN</span> sont nombreuses ; on oppose les causes fréquentes aux causes exceptionnelles.</p>\n      <table >\n        <thead><tr><th>Fréquence</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Les plus fréquentes</td><td>\n            <strong>Infections respiratoires apnéisantes :</strong> <span class=\"kw-etio\">VRS</span> ; <span class=\"kw-etio\">coqueluche</span> ; rhinovirus<br>\n            <strong>Infections virales graves :</strong> <span class=\"kw-etio\">myocardites</span> ; <span class=\"kw-etio\">méningites</span> ; encéphalites<br>\n            <strong>Infections bactériennes foudroyantes :</strong> <span class=\"kw-etio\">streptocoque du groupe B</span> ; <span class=\"kw-etio\">méningocoque</span> ; <span class=\"kw-etio\">pneumocoque</span><br>\n            <strong>Autres :</strong> déshydratation aiguë ; accident de literie ; <span class=\"kw-etio\">inhalation de corps étranger</span> ; <span class=\"kw-alerte\">strangulation</span> ; intoxication ; <span class=\"kw-etio\">maltraitance</span></td></tr>\n          <tr><td>Causes exceptionnelles</td><td>\n            <span class=\"kw-etio\">Troubles du rythme cardiaque</span> ; malformations méconnues (cardiaques, digestives) ; <span class=\"kw-etio\">maladies métaboliques héréditaires</span> ; <span class=\"kw-etio\">syndrome d'Ondine</span> (hypoventilation alvéolaire centrale)</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-def\">MSN</span> (~<span class=\"kw-chiffre\">40 %</span> des MIN du nourrisson &lt;<span class=\"kw-chiffre\"> 1 an</span>) reste un <span class=\"kw-def\">diagnostic d'exclusion</span> : multifactorielle, une <span class=\"kw-etio\">infection virale bénigne</span> (VAS) y est souvent retrouvée comme <strong>facteur déclenchant</strong>, entraînant un <span class=\"kw-clinique\">dérèglement du système nerveux autonome</span> — le nourrisson ne parvient pas à se réveiller pour dégager ses voies aériennes.</p>\n      <div class=\"callout callout-warn\"><strong>À jour du référentiel.</strong> L'<span class=\"kw-etio\">hyperthermie maligne</span> a été <strong>supprimée</strong> de la liste des causes dans le nouveau référentiel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 163 — Coqueluche · 158 — Sepsis et <span class=\"kw-alerte\">choc septique</span> · 286 — Diarrhée aiguë - déshydratation · 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"345-4","rang":"A","rubrique":"Définition","titre":"Malaise grave du nourrisson : connaître la définition","contenu":"<p>Le <span class=\"kw-def\">malaise grave du nourrisson</span> est un <strong>motif fréquent</strong> de consultation aux <span class=\"kw-clinique\">urgences pédiatriques</span>. Il se définit comme un <span class=\"kw-clinique\">accident inopiné et brutal</span> associant, à des degrés variables :</p>\n      <ul>\n        <li><strong>Modification du <span class=\"kw-clinique\">tonus</span> :</strong> <span class=\"kw-clinique\">hypotonie</span> ou <span class=\"kw-clinique\">hypertonie</span></li>\n        <li><strong>Modification de la <span class=\"kw-clinique\">coloration</span> :</strong> <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">cyanose</span>, parfois érythrose</li>\n        <li><strong>± modification du <span class=\"kw-clinique\">rythme respiratoire</span> :</strong> bradypnée, tachypnée, <span class=\"kw-clinique\">apnées</span></li>\n        <li><strong>± <span class=\"kw-clinique\">perte de connaissance</span></strong></li>\n      </ul>\n      <table >\n        <thead><tr><th>Item</th><th>Repère</th></tr></thead>\n        <tbody>\n          <tr><td>Terrain</td><td>Nourrissons <span class=\"kw-chiffre\">&lt; 6 mois</span> ; prédominance <span class=\"kw-etio\">masculine</span></td></tr>\n          <tr><td>« Grave » ?</td><td>Le malaise est <strong>fréquemment bénin</strong>, mais l'<span class=\"kw-clinique\">impression de mort imminente</span> le fait vivre comme dramatique par les parents (<span class=\"kw-clinique\">manœuvres de réanimation</span> : <span class=\"kw-clinique\">bouche-à-bouche</span>, secouage…). Il faut distinguer le <strong>vécu</strong> du <strong>réel degré de gravité</strong> sur des critères objectifs.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Physiopathologie.</strong> Une <span class=\"kw-clinique\">hypertonie vagale</span> sous-tend fréquemment les malaises compliquant un <span class=\"kw-etio\">RGO</span> ou une <span class=\"kw-etio\">douleur aiguë</span>.</div>","frequence":0},{"id":"345-5","rang":"A","rubrique":"Diagnostic positif","titre":"Malaise grave du nourrisson : identifier un malaise","contenu":"<p>L'<span class=\"kw-def\">identification</span> repose sur l'<span class=\"kw-clinique\">anamnèse</span> : la description est le plus souvent rapportée par les <span class=\"kw-clinique\">parents, seuls témoins</span> de l'épisode. Les <span class=\"kw-clinique\">signes fonctionnels</span> sont transitoires et le <strong>premier <span class=\"kw-clinique\">examen clinique</span> est souvent normal</strong> au moment de la consultation.</p>\n      <p>L'<span class=\"kw-clinique\">examen clinique</span> doit être <strong>complet</strong>, comportant notamment :</p>\n      <ul>\n        <li>Mesure du <span class=\"kw-clinique\">périmètre crânien</span> (PC)</li>\n        <li>Recherche de bruits respiratoires</li>\n        <li>Recherche d'<span class=\"kw-alerte\">hématomes</span> et d'<span class=\"kw-alerte\">ecchymoses</span> (orientation <span class=\"kw-etio\">maltraitance</span>)</li>\n        <li>Recherche d'un <span class=\"kw-clinique\">rétrognathisme</span>, d'un palais ogival</li>\n        <li>Observation de l'enfant durant son <span class=\"kw-clinique\">sommeil</span> et durant un <span class=\"kw-clinique\">repas lacté</span> (<span class=\"kw-clinique\">succion-déglutition</span>)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Un <span class=\"kw-clinique\">examen normal à distance</span> de l'épisode <strong>n'exclut aucune cause</strong>, notamment <span class=\"kw-etio\">neurologique</span> : l'<span class=\"kw-clinique\">anamnèse</span> reste l'élément clé pour évaluer la <span class=\"kw-alerte\">gravité</span> et l'<span class=\"kw-etio\">étiologie</span>.</div>","frequence":0},{"id":"345-6","rang":"A","rubrique":"Identifier une urgence","titre":"Malaise grave du nourrisson : identifier les situations d’urgence","contenu":"<p>Identifier une <span class=\"kw-alerte\">situation d'urgence</span> consiste à rechercher systématiquement les <span class=\"kw-alerte\">critères cliniques de gravité</span>.</p>\n      <table >\n        <thead><tr><th>Système</th><th>Critères de gravité</th></tr></thead>\n        <tbody>\n          <tr><td>Hémodynamiques</td><td><span class=\"kw-alerte\">Teint gris</span> ; bradycardie ou tachycardie ; hypo- ou hypertension ; <span class=\"kw-alerte\">allongement du TRC</span> ; <span class=\"kw-alerte\">état de choc</span> ; signes d'<span class=\"kw-alerte\">insuffisance cardiaque</span></td></tr>\n          <tr><td>Ventilatoires</td><td><span class=\"kw-alerte\">Cyanose</span> ; irrégularités respiratoires persistantes (bradypnée, <span class=\"kw-alerte\">apnée</span>) ; signes de lutte ; <span class=\"kw-alerte\">SpO₂ &lt; 90 %</span> sous air</td></tr>\n          <tr><td>Neurologiques</td><td>Geignement ; <span class=\"kw-alerte\">bombement de la fontanelle</span> ; augmentation du périmètre crânien ; <span class=\"kw-alerte\">troubles de conscience</span> (somnolence, <span class=\"kw-alerte\">coma</span>) ; déficit focalisé ; hypotonie/hypertonie axiale ou périphérique ; mouvements anormaux (clonies, mâchonnements, pédalage)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Dogme d'orientation.</strong> Tout nourrisson ayant fait un <span class=\"kw-clinique\">malaise authentifié et récent</span> (<span class=\"kw-chiffre\">≤ 24-48 h</span>) doit être adressé aux <strong>urgences pédiatriques</strong> pour évaluation.</div>\n      <table >\n        <thead><tr><th>Orientation</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Surveillance minimale</td><td>Malaise d'allure bénigne (ex. <span class=\"kw-etio\">régurgitations</span> avec faciès <span class=\"kw-clinique\">érythrosique</span>), <strong>sans</strong> signe de gravité clinique/paraclinique → suivi ambulatoire après une surveillance courte de <span class=\"kw-chiffre\">6-12 h</span></td></tr>\n          <tr><td>Hospitalisation ≥ <span class=\"kw-chiffre\">24-48 h</span></td><td><span class=\"kw-alerte\">Anamnèse</span> faisant redouter une cause grave ; <span class=\"kw-alerte\">critères de gravité</span> clinique/paraclinique ; <span class=\"kw-alerte\">inquiétude parentale majeure</span> ou conditions difficiles de retour à domicile → monitoring cardiorespiratoire</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de choc · 346 — Convulsion chez le nourrisson/enfant</em></p>","frequence":2},{"id":"345-7","rang":"B","rubrique":"Diagnostic positif","titre":"Malaise grave du nourrisson : connaître les modalités de l’enquête étiologique","contenu":"<p>L'<span class=\"kw-def\">enquête étiologique</span> combine la recherche des <span class=\"kw-etio\">causes possibles</span>, une <strong>anamnèse structurée</strong> et un <strong>bilan paraclinique</strong>.</p>\n      <p><strong>Étiologies à évoquer devant un malaise</strong> :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td>Reflux gastro-œsophagien</td><td><span class=\"kw-etio\">RGO</span> (hypertonie vagale)</td></tr>\n          <tr><td>Douleur aiguë</td><td>Œsophagite ; <span class=\"kw-etio\">invagination intestinale aiguë</span> ; <span class=\"kw-alerte\">sévices physiques</span> ; <span class=\"kw-etio\">ischémie myocardique</span> (anomalie d'implantation des coronaires)</td></tr>\n          <tr><td>Obstruction mécanique haute</td><td>Rhinite obstructive ; vomissements / fausses routes ; <span class=\"kw-etio\">inhalation de corps étranger</span> mobile</td></tr>\n          <tr><td>Neurologiques</td><td><span class=\"kw-etio\">Crise fébrile</span> ; <span class=\"kw-etio\">crise épileptique</span> ; <span class=\"kw-alerte\">hémorragies intra/péricérébrales</span> ; <span class=\"kw-alerte\">syndrome du bébé secoué</span></td></tr>\n          <tr><td>Infectieuses</td><td><span class=\"kw-etio\">Apnées</span> (bronchiolite, coqueluche, grippe, adénovirus) ; <span class=\"kw-alerte\">sepsis</span></td></tr>\n          <tr><td>Autres</td><td>\n            <strong>Cardiaques :</strong> <span class=\"kw-etio\">tachycardie supraventriculaire</span> ; <span class=\"kw-etio\">syndrome du QT long</span> ; <span class=\"kw-etio\">cardiopathie malformative</span><br>\n            <strong>Métaboliques :</strong> <span class=\"kw-etio\">hypoglycémie</span> ; <span class=\"kw-etio\">hypocalcémie</span> ; <span class=\"kw-etio\">anomalie de la β-oxydation des acides gras</span><br>\n            <strong>Toxiques :</strong> <span class=\"kw-etio\">CO</span> ; médicament<br>\n            <strong>Allergie :</strong> <span class=\"kw-etio\">anaphylaxie</span> ; SEIPA<br>\n            <strong>Mécaniques :</strong> <span class=\"kw-etio\">asphyxie par enfouissement facial</span> ; trachéomalacie<br>\n            <strong>Autres :</strong> spasme du sanglot ; <span class=\"kw-alerte\">syndrome de Münchhausen</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Anamnèse — points clés</strong> :</p>\n      <ul>\n        <li><strong>ATCD familiaux :</strong> <span class=\"kw-def\">MIN</span>, décès en bas âge, malaises, terrain vagal familial, consanguinité, cardiopathie</li>\n        <li><strong>Terrain :</strong> déroulement de la grossesse, <span class=\"kw-etio\">prématurité</span>, <span class=\"kw-etio\">RGO</span>, développement psychomoteur, vaccination</li>\n        <li><strong>Avant / pendant / après le malaise :</strong> contexte (biberon, change, repas, coucher, sommeil), prodromes (<span class=\"kw-clinique\">fièvre</span>, troubles digestifs), chronologie et <span class=\"kw-clinique\">durée</span>, mode de récupération (spontanée vs aidée), récidive</li>\n      </ul>\n      <p><strong>Bilan paraclinique systématique</strong> (en urgence) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">BU</span> ; <span class=\"kw-imagerie\">ECG</span> avec mesure du <span class=\"kw-bio\">QT corrigé</span> ; <span class=\"kw-imagerie\">RXT de face</span></li>\n        <li><span class=\"kw-bio\">Glycémie</span> capillaire (dès l'arrivée) puis veineuse</li>\n        <li><span class=\"kw-bio\">NFS-plaquettes</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">ionogramme</span> sanguin ; créatininémie ; <span class=\"kw-bio\">urée</span> ; transaminases ; <span class=\"kw-bio\">PCT</span> ; <span class=\"kw-bio\">calcémie</span> ; lactate</li>\n      </ul>\n      <p><strong>Bilan à visée étiologique</strong> (orienté) :</p>\n      <ul>\n        <li><strong>Cause neurologique :</strong> <span class=\"kw-bio\">ammoniémie</span> + <span class=\"kw-bio\">gaz du sang</span> + lactate ; <span class=\"kw-imagerie\">EEG</span> ; <span class=\"kw-imagerie\">imagerie cérébrale</span> (<span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span>) ; <span class=\"kw-clinique\">fond d'œil</span></li>\n        <li><strong><span class=\"kw-imagerie\">Holter</span> cardiaque</strong> si <span class=\"kw-imagerie\">anomalies à l'ECG</span> (troubles du rythme/conduction) ou <span class=\"kw-clinique\">récidives</span> de malaise sans étiologie retrouvée</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 346 — Convulsion chez le nourrisson/enfant · 238 — Souffle cardiaque de l'enfant · 338 — Œdème de Quincke - <span class=\"kw-alerte\">anaphylaxie</span> · 337 — Intoxication aiguë</em></p>","frequence":3},{"id":"345-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures préventives du malaise grave et de la mort inattendue du nourrisson","contenu":"<p>Les <span class=\"kw-def\">mesures préventives</span> sont essentielles : les campagnes autour du couchage ont fait <strong>baisser les décès par MSN de <span class=\"kw-chiffre\">75 %</span> entre 1991 et 2005</strong>. Elles sont rappelées dans le <span class=\"kw-clinique\">carnet de santé</span>.</p>\n      <table >\n        <thead><tr><th>Recommandation</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Couchage recommandé</td><td>\n            <span class=\"kw-ttt\">Décubitus dorsal</span><br>\n            Lit dans la <span class=\"kw-ttt\">même pièce que les parents</span> les premiers mois<br>\n            Lit <strong>vide</strong> : <span class=\"kw-ttt\">sans oreiller, ni couette, ni couverture</span><br>\n            <span class=\"kw-ttt\">Berceau rigide</span>, matelas <span class=\"kw-ttt\">ferme et à plat</span>, drap-housse seul<br>\n            Température de la chambre <span class=\"kw-chiffre\">18-20 °C</span></td></tr>\n          <tr><td>À ne pas faire</td><td>\n            <span class=\"kw-alerte\">Pas de co-sleeping</span> (lit parental)<br>\n            Ne pas <span class=\"kw-alerte\">surcouvrir</span> l'enfant (préférer turbulette / gigoteuse)<br>\n            Pas de <span class=\"kw-alerte\">cale-bébé, cale-tête, boudins, cocoon, réducteurs de lit</span><br>\n            Proscrire le <span class=\"kw-alerte\">tabagisme familial</span><br>\n            Lits à <span class=\"kw-alerte\">parois pleines</span> non recommandés</td></tr>\n          <tr><td>Encouragé</td><td><span class=\"kw-ttt\">Allaitement maternel</span> ; proposer une <span class=\"kw-ttt\">tétine</span> à l'endormissement</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Bonus.</strong> Ces conditions de couchage réduisent aussi le risque de <span class=\"kw-clinique\">plagiocéphalie positionnelle</span> (matelas ferme à plat, liberté de mouvement, champ visuel large).</div>\n      <div class=\"callout callout-warn\"><strong>Prise en charge médicale de la MIN (rang C).</strong> Tous les cas de MIN doivent être explorés, idéalement dans un <span class=\"kw-clinique\">centre de référence MIN</span> (≠ institut médico-légal) : recueil du <strong>consentement écrit</strong> des parents, investigations étiologiques cliniques et paracliniques, proposition systématique d'une <strong>autopsie médicale</strong> par un anatomopathologiste spécialisé. La <span class=\"kw-alerte\">MIN n'est pas un obstacle médico-légal</span> ; en revanche, un <strong>refus d'autopsie</strong> peut faire suspecter une <span class=\"kw-etio\">maltraitance</span> et constituer un obstacle médico-légal. Identifier la cause précise du décès est un point de départ pour le <span class=\"kw-clinique\">travail de deuil</span> et la prise en charge d'un futur enfant du couple.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — Vaccination · 57 — Maltraitance, enfant en danger · 144 — Deuil</em></p>","frequence":2}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU &amp; Pièges » et « Stratégie &amp; CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Dogme :</strong> tout nourrisson ayant fait un <span class=\"kw-clinique\">malaise authentifié et récent</span> (<span class=\"kw-chiffre\">≤ 24-48 h</span>) doit être adressé aux <strong>urgences pédiatriques</strong> pour évaluation.<br><strong>Dès l'arrivée :</strong> <span class=\"kw-bio\">glycémie capillaire</span> (puis veineuse), <span class=\"kw-bio\">BU</span>, <span class=\"kw-imagerie\">ECG</span> avec <span class=\"kw-bio\">QT corrigé</span>, <span class=\"kw-imagerie\">RXT de face</span> — bilan prescrit <strong>en urgence</strong>.<br><strong>Détresse vitale :</strong> traiter sans délai une <span class=\"kw-alerte\">cause de détresse vitale</span> (exceptionnel).</p>","hospit":"<p><strong>Surveillance ambulatoire <span class=\"q\">— malaise d'allure bénigne</span></strong></p><p>Retour à domicile après une <span class=\"kw-chiffre\">surveillance courte de 6-12 h</span></p><ul><li>Origine évidemment bénigne (ex. <span class=\"kw-etio\">régurgitations</span> avec faciès <span class=\"kw-clinique\">érythrosique</span>)</li><li><strong>Aucun</strong> <span class=\"kw-alerte\">signe de gravité</span> clinique ni paraclinique</li></ul><p><strong>Hospitalisation <span class=\"q\">— <span class=\"kw-chiffre\">≥ 24-48 h</span></span></strong></p><p><span class=\"kw-ttt\">Monitoring cardiorespiratoire</span> + poursuite des investigations étiologiques</p><ul><li><span class=\"kw-clinique\">Anamnèse</span> faisant redouter une cause grave (sémiologie, circonstances)</li><li><span class=\"kw-alerte\">Critères de gravité</span> clinique et/ou paraclinique</li><li><span class=\"kw-clinique\">Inquiétude parentale majeure</span> ou conditions difficiles de retour à domicile</li></ul>","redflags":"<ul><li><strong>Hémodynamiques :</strong> <span class=\"kw-alerte\">teint gris</span> ; bradycardie ou tachycardie ; hypo- ou hypertension</li><li><span class=\"kw-alerte\">Allongement du temps de recoloration cutanée</span> ; <span class=\"kw-alerte\">état de choc</span> ; signes d'<span class=\"kw-alerte\">insuffisance cardiaque</span></li><li><strong>Ventilatoires :</strong> <span class=\"kw-alerte\">cyanose</span> ; irrégularités respiratoires persistantes (bradypnée, <span class=\"kw-alerte\">apnée</span>) ; signes de lutte</li><li><span class=\"kw-alerte\">SpO₂ &lt; 90 %</span> sous air</li><li><strong>Neurologiques :</strong> geignement ; <span class=\"kw-alerte\">bombement de la fontanelle</span> ; augmentation du <span class=\"kw-clinique\">périmètre crânien</span></li><li><span class=\"kw-alerte\">Troubles de conscience</span> (somnolence, <span class=\"kw-alerte\">coma</span>) ; <span class=\"kw-alerte\">déficit focalisé</span> ; hypotonie/hypertonie axiale ou périphérique</li><li><span class=\"kw-alerte\">Mouvements anormaux</span> (clonies, mâchonnements, pédalage)</li></ul>","principes":"<p>La PEC du malaise est avant tout <strong>évaluative</strong> ; le poids de l'item porte sur la <strong>prévention</strong> de la MIN/MSN et la <strong>PEC médicale</strong> du décès.</p><p><strong>Prévention de la MIN/MSN <span class=\"q\">— couchage recommandé</span></strong></p><p>Les campagnes sur le couchage ont fait <span class=\"kw-chiffre\">baisser de 75 %</span> les décès par MSN (1991-2005)</p><ul><li><span class=\"kw-ttt\">Décubitus dorsal</span> ; lit dans la <span class=\"kw-ttt\">même pièce que les parents</span> les premiers mois</li><li>Lit <strong>vide</strong> : <span class=\"kw-ttt\">sans oreiller, ni couette, ni couverture</span> ; <span class=\"kw-ttt\">berceau rigide</span>, matelas <span class=\"kw-ttt\">ferme et à plat</span>, drap-housse seul</li><li>Chambre à <span class=\"kw-chiffre\">18-20 °C</span> ; <span class=\"kw-ttt\">allaitement maternel</span> encouragé ; <span class=\"kw-ttt\">tétine</span> à l'endormissement</li></ul><p><strong>À proscrire</strong></p><ul><li><span class=\"kw-ci\">Co-sleeping</span> (lit parental) ; <span class=\"kw-ci\">surcouverture</span> de l'enfant (préférer turbulette / gigoteuse)</li><li><span class=\"kw-ci\">Cale-bébé, cale-tête, boudins, cocoon, réducteurs de lit</span> ; lits à <span class=\"kw-ci\">parois pleines</span></li><li><span class=\"kw-ci\">Tabagisme familial</span></li></ul><p><strong>PEC médicale de la MIN <span class=\"q\">— rang C</span></strong></p><p>La <span class=\"kw-def\">MIN n'est pas un obstacle médico-légal</span> ; un <span class=\"kw-alerte\">refus d'autopsie</span> peut faire suspecter une <span class=\"kw-etio\">maltraitance</span></p><ul><li>Explorer <strong>tous</strong> les cas dans un <span class=\"kw-ttt\">centre de référence MIN</span> (≠ institut médico-légal)</li><li><span class=\"kw-ttt\">Consentement écrit</span> des parents (autopsie + examens génétiques)</li><li><span class=\"kw-ttt\">Autopsie médicale</span> systématique par un anatomopathologiste spécialisé</li></ul>","suivi":"<p><strong>En observation :</strong> <span class=\"kw-ttt\">monitoring cardiorespiratoire</span>, poursuite des investigations étiologiques, vérification de la bonne évolution clinique.<br><strong><span class=\"kw-imagerie\">Holter</span> cardiaque :</strong> si <span class=\"kw-imagerie\">anomalies à l'ECG</span> (troubles du rythme / conduction) ou <span class=\"kw-clinique\">récidives</span> de malaise sans étiologie retrouvée.<br><strong>Après une MIN :</strong> identifier la cause précise amorce le <span class=\"kw-clinique\">travail de deuil</span> et conditionne la PEC d'un futur enfant du couple.</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/malaise-grave-du-nourrisson","label":"pedia-univ.fr — Malaise grave du nourrisson (référentiel)"}],"cards":[{"i":"0c5edab071f5","n":345,"o":"345-1","u":"Définition","t":"Mort inattendue du nourrisson : connaître la définition","q":"Quelle est la particularité de la Mort Inattendue du Nourrisson (MIN) de cause indéterminée ?","a":"<p>Une MIN est qualifiée de cause indéterminée lorsque les <strong>investigations post-mortem sont incomplètes</strong>. La MSN représente environ <strong>40 %</strong> des MIN chez les nourrissons de moins de 1 an. Le tableau typique est un nourrisson âgé de <strong>2 à 4 mois</strong> retrouvé mort dans son sommeil.</p>"},{"i":"bfba5e837896","n":345,"o":"345-1","u":"Définition","t":"Mort inattendue du nourrisson : connaître la définition","q":"Quelle est la définition de la Mort Inattendue du Nourrisson (MIN) ?","a":"<p>La Mort Inattendue du Nourrisson (MIN) désigne une mort survenant <strong>brutalement</strong> chez un nourrisson de <strong>moins de 2 ans</strong>, alors que rien dans ses antécédents connus ne pouvait la laisser prévoir. Il n'existe <strong>pas de code CIM</strong> dédié spécifiquement à la MIN.</p>"},{"i":"d3dade05e228","n":345,"o":"345-1","u":"Définition","t":"Mort inattendue du nourrisson : connaître la définition","q":"Comment la Mort Subite du Nourrisson (MSN ou SIDS) est-elle définie ?","a":"<p>La Mort Subite du Nourrisson (MSN) est un <strong>diagnostic d'exclusion</strong>. Elle correspond à une mort pour laquelle <strong>aucune cause directe n'est identifiée</strong> malgré des investigations exhaustives :</p><ul><li>Enquête sur les lieux du décès</li><li>Anamnèse</li><li>Examen physique</li><li>Bilan paraclinique</li><li>Autopsie</li></ul><p>La MSN possède un code CIM existant et concerne les nourrissons de <strong>moins de 1 an</strong>.</p>"},{"i":"1a3556ac1735","n":345,"o":"345-2","u":"Epidémiologie","t":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","q":"Quel est le modèle du triple risque de la mort subite du nourrisson (MSN) ?","a":"<p>Le modèle du triple risque de la MSN repose sur la concomitance de <strong>trois facteurs</strong> : un <strong>enfant vulnérable</strong>, un <strong>environnement de sommeil à risque</strong> et une <strong>période critique de son développement</strong>.</p>"},{"i":"5998e15a820f","n":345,"o":"345-2","u":"Epidémiologie","t":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","q":"Quels sont les facteurs de risque de la mort subite du nourrisson (MSN) liés aux antécédents personnels du nourrisson ?","a":"<p>Les facteurs de risque liés aux antécédents personnels du nourrisson incluent la <strong>prématurité</strong>, un <strong>retard de croissance intra-utérin (RCIU)</strong>, le <strong>tabagisme anténatal</strong> et le <strong>sexe masculin</strong>.</p>"},{"i":"5dfbf2b6001f","n":345,"o":"345-2","u":"Epidémiologie","t":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","q":"Quelle est la définition épidémiologique de la mort inattendue du nourrisson (MIN) et de la mort subite du nourrisson (MSN) ?","a":"<p>La <strong>mort inattendue du nourrisson (MIN)</strong> est une catégorie épidémiologique globale. La <strong>mort subite du nourrisson (MSN)</strong> est un sous-groupe spécifique de la MIN, codé selon la CIM, utilisé pour le suivi épidémiologique.</p>"},{"i":"b3f0fe8ff71f","n":345,"o":"345-2","u":"Epidémiologie","t":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","q":"Quels sont les facteurs de risque de la mort subite du nourrisson (MSN) liés à l'âge, à la période et au contexte social ?","a":"<ul><li>L'âge le plus à risque est <strong>inférieur à 6 mois</strong> et la période est l'<strong>hiver</strong>.</li><li>Les facteurs liés au contexte social sont une <strong>mère jeune</strong>, une <strong>grossesse non suivie</strong> et un <strong>milieu défavorisé</strong>.</li></ul>"},{"i":"d1d0a7ff2b68","n":345,"o":"345-2","u":"Epidémiologie","t":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","q":"Quels sont les facteurs de risque liés à l'environnement et aux circonstances de la mort subite du nourrisson (MSN) ?","a":"<ul><li><strong>Couchage en décubitus ventral</strong>.</li><li><strong>Enfouissement du visage</strong> dans la literie.</li><li><strong>Hyperflexion cervicale</strong>.</li><li><strong>Tabagisme parental</strong>.</li><li>Lieu <strong>surchauffé</strong> ou enfant <strong>trop couvert</strong>.</li><li><strong>Co-sleeping</strong> (partage du lit).</li><li>Nourrisson <strong>isolé seul dans une chambre</strong>.</li></ul>"},{"i":"f6cd4334d0b0","n":345,"o":"345-2","u":"Epidémiologie","t":"Mort inattendue du nourrisson : connaître l’épidémiologie et facteurs de risque","q":"Quels sont les chiffres clés de l'épidémiologie de la mort inattendue du nourrisson (MIN) et de la mort subite du nourrisson (MSN) en France ?","a":"<ul><li>La MIN chez les enfants de <strong>moins de 1 an</strong> représente <strong>350 à 400 décès par an</strong>.</li><li>La MIN chez les enfants de <strong>1 à 2 ans</strong> est environ <strong>10 fois moins fréquente</strong>.</li><li>L'incidence de la MSN est de <strong>2 à 3 pour 10 000 naissances vivantes</strong>, soit environ <strong>150 décès par an en France</strong>.</li><li>La MSN représente environ <strong>6 % de la mortalité infantile</strong>.</li></ul>"},{"i":"8473d66ff4ad","n":345,"o":"345-3","u":"Étiologies","t":"Mort inattendue du nourrisson : connaître les aspects étiologiques (causes fréquentes)","q":"En dehors des infections, quelles sont les autres causes fréquentes de Mort Inattendue du Nourrisson ?","a":"<ul><li><strong>Déshydratation aiguë</strong>.</li><li><strong>Accident de literie</strong>.</li><li><strong>Inhalation de corps étranger</strong>.</li><li><strong>Strangulation</strong>.</li><li><strong>Intoxication</strong>.</li><li><strong>Maltraitance</strong>.</li></ul>"},{"i":"85a3be60213a","n":345,"o":"345-3","u":"Étiologies","t":"Mort inattendue du nourrisson : connaître les aspects étiologiques (causes fréquentes)","q":"Quelle est la définition de la Mort Inattendue du Nourrisson (MIN) et sa proportion chez le nourrisson de moins d'un an ?","a":"<p>La Mort Inattendue du Nourrisson (MIN) est un diagnostic d'exclusion, souvent multifactorielle. Environ <strong>40% des MIN</strong> chez le nourrisson de moins d'un an sont des Morts Subites du Nourrisson (MSN).</p>"},{"i":"97dacbcba35c","n":345,"o":"345-3","u":"Étiologies","t":"Mort inattendue du nourrisson : connaître les aspects étiologiques (causes fréquentes)","q":"Quelles sont les causes exceptionnelles de Mort Inattendue du Nourrisson ?","a":"<ul><li><strong>Troubles du rythme cardiaque</strong>.</li><li><strong>Malformations méconnues</strong> (cardiaques, digestives).</li><li><strong>Maladies métaboliques héréditaires</strong>.</li><li><strong>Syndrome d'Ondine</strong> (hypoventilation alvéolaire centrale).</li></ul>"},{"i":"c9dd94996456","n":345,"o":"345-3","u":"Étiologies","t":"Mort inattendue du nourrisson : connaître les aspects étiologiques (causes fréquentes)","q":"Quels sont les mécanismes physiopathologiques principaux de la Mort Subite du Nourrisson (MSN) ?","a":"<p>Bien que multifactorielle, la MSN est souvent déclenchée par une <strong>infection virale bénigne des voies aériennes supérieures</strong>. Cela entraîne un <strong>dérèglement du système nerveux autonome</strong>, empêchant le nourrisson de se réveiller pour dégager ses voies aériennes.</p>"},{"i":"f4c9feaebab1","n":345,"o":"345-3","u":"Étiologies","t":"Mort inattendue du nourrisson : connaître les aspects étiologiques (causes fréquentes)","q":"Quelles sont les causes infectieuses fréquentes de Mort Inattendue du Nourrisson ?","a":"<ul><li><strong>Infections respiratoires apnéisantes</strong> : notament le Virus Respiratoire Syncytial (<strong>VRS</strong>), la coqueluche, le rhinovirus.</li><li><strong>Infections virales graves</strong> : myocardites, méningites, encéphalites.</li><li><strong>Infections bactériennes foudroyantes</strong> : dues au <strong>streptocoque du groupe B</strong>, au <strong>méningocoque</strong>, ou au <strong>pneumocoque</strong>.</li></ul>"},{"i":"334f230b55c0","n":345,"o":"345-4","u":"Définition","t":"Malaise grave du nourrisson : connaître la définition","q":"Quelle est la définition du malaise grave du nourrisson ?","a":"<p>Le malaise grave du nourrisson est un accident <strong>inopiné</strong> et <strong>brutal</strong> qui associe, à des degrés variables, plusieurs signes cliniques.</p>"},{"i":"6e914974fbee","n":345,"o":"345-4","u":"Définition","t":"Malaise grave du nourrisson : connaître la définition","q":"Quels sont les signes cliniques associés au malaise grave du nourrisson ?","a":"<ul><li>Modification du <strong>tonus</strong> : hypotonie ou hypertonie.</li><li>Modification de la <strong>coloration</strong> : pâleur, cyanose, parfois érythrose.</li><li>± Modification du <strong>rythme respiratoire</strong> : bradypnée, tachypnée, apnées.</li><li>± <strong>Perte de connaissance</strong>.</li></ul>"},{"i":"cff30c956b34","n":345,"o":"345-4","u":"Définition","t":"Malaise grave du nourrisson : connaître la définition","q":"Quel terrain est concerné par le malaise grave du nourrisson ?","a":"<p>Le malaise grave du nourrisson concerne principalement les nourrissons de <strong>moins de 6 mois</strong>, avec une <strong>prédominance masculine</strong>.</p>"},{"i":"33ac94ff4dbf","n":345,"o":"345-5","u":"Diagnostic positif","t":"Malaise grave du nourrisson : identifier un malaise","q":"Quel est l'élément clé anamnistique lors de l'identification d'un malaise grave du nourrisson ?","a":"<p>L'<strong>anamnèse</strong> est l'élément clé, car la description est le plus souvent rapportée par les <strong>parents</strong>, seuls témoins de l'épisode, les signes fonctionnels étant transitoires.</p>"},{"i":"6cb8e08bb0cd","n":345,"o":"345-5","u":"Diagnostic positif","t":"Malaise grave du nourrisson : identifier un malaise","q":"Pourquoi l'examen clinique initial est-il souvent normal lors de la consultation pour un malaise grave du nourrisson, et quelle est l'implication diagnostique ?","a":"<p>L'examen clinique initial est souvent normal car les <strong>signes fonctionnels sont transitoires</strong>. Un <strong>examen normal</strong> à distance de l'épisode <strong>n'exclut aucune cause</strong> (notamment neurologique). L'anamnèse reste cruciale pour évaluer la gravité et l'étiologie.</p>"},{"i":"fd006e4db85c","n":345,"o":"345-5","u":"Diagnostic positif","t":"Malaise grave du nourrisson : identifier un malaise","q":"Quels sont les éléments spécifiques à rechercher lors de l'examen clinique pour identifier un malaise grave du nourrisson ?","a":"<ul><li>Mesure du <strong>périmètre crânien (PC)</strong></li><li>Recherche de <strong>bruits respiratoires</strong></li><li>Recherche d'<strong>hématomes et d'ecchymoses</strong> (orientation maltraitance)</li><li>Recherche d'un <strong>rétrognathisme</strong>, d'un <strong>palais ogival</strong></li><li>Observation de l'enfant durant son <strong>sommeil</strong> et durant un <strong>repas lacté</strong> (succion-déglutition)</li></ul>"},{"i":"8e8e794a1e01","n":345,"o":"345-6","u":"Identifier une urgence","t":"Malaise grave du nourrisson : identifier les situations d’urgence","q":"Quels sont les critères cliniques neurologiques permettant d'identifier une situation d'urgence lors d'un malaise grave du nourrisson ?","a":"<p>Les critères cliniques neurologiques d'urgence chez un nourrisson sont :</p><ul><li>Un <strong>geignement</strong>.</li><li>Un <strong>bombement de la fontanelle</strong> ou une <strong>augmentation du périmètre crânien</strong>.</li><li>Des <strong>troubles de la conscience</strong> (somnolence, coma).</li><li>Un <strong>déficit neurologique focalisé</strong>.</li><li>Une <strong>hypotonie</strong> ou une <strong>hypertonie axiale ou périphérique</strong>.</li><li>Des <strong>mouvements anormaux</strong> (clonies, mâchonnements, pédalage).</li></ul>"},{"i":"be93cbf962c6","n":345,"o":"345-6","u":"Identifier une urgence","t":"Malaise grave du nourrisson : identifier les situations d’urgence","q":"Quelle est la conduite à tenir systématique pour un nourrisson ayant fait un malaise grave authentifié et récent ?","a":"<p>Tout nourrisson ayant fait un malaise authentifié et récent (<strong>datant de moins de 24 à 48 heures</strong>) doit impérativement être <strong>adressé aux urgences pédiatriques</strong> pour une évaluation complète.</p>"},{"i":"e045793d60d7","n":345,"o":"345-6","u":"Identifier une urgence","t":"Malaise grave du nourrisson : identifier les situations d’urgence","q":"Quels sont les critères cliniques hémodynamiques permettant d'identifier une situation d'urgence lors d'un malaise grave du nourrisson ?","a":"<p>Les critères cliniques hémodynamiques d'urgence chez un nourrisson sont :</p><ul><li>Un <strong>teint gris</strong>.</li><li>Une <strong>bradycardie</strong> ou une <strong>tachycardie</strong>.</li><li>Une <strong>hypotension</strong> ou une <strong>hypertension</strong>.</li><li>Un <strong>allongement du temps de recoloration cutanée (TRC)</strong>.</li><li>Des signes d'<strong>état de choc</strong>.</li><li>Des signes d'<strong>insuffisance cardiaque</strong>.</li></ul>"},{"i":"f47c8e14bad2","n":345,"o":"345-6","u":"Identifier une urgence","t":"Malaise grave du nourrisson : identifier les situations d’urgence","q":"Quels sont les critères cliniques ventilatoires permettant d'identifier une situation d'urgence lors d'un malaise grave du nourrisson ?","a":"<p>Les critères cliniques ventilatoires d'urgence chez un nourrisson sont :</p><ul><li>Une <strong>cyanose</strong>.</li><li>Des <strong>irrégularités respiratoires persistantes</strong> (bradypnée, apnée).</li><li>Des <strong>signes de lutte respiratoire</strong>.</li><li>Une <strong>SpO₂ inférieure à 90 % sous air ambiant</strong>.</li></ul>"},{"i":"4a943bf72b55","n":345,"o":"345-8","u":"Prise en charge","t":"Connaître les mesures préventives du malaise grave et de la mort inattendue du nourrisson","q":"Quels sont les facteurs connus pour réduire le risque de mort inattendue du nourrisson et qui sont à encourager ?","a":"<p>L'<strong>allaitement maternel</strong> est encouragé, de même que la proposition d'une <strong>tétine à l'endormissement</strong>.</p>"},{"i":"4d1d7f7ae5df","n":345,"o":"345-8","u":"Prise en charge","t":"Connaître les mesures préventives du malaise grave et de la mort inattendue du nourrisson","q":"Quelles sont les pratiques à proscrire concernant le couchage et l'environnement du nourrisson pour prévenir la mort inattendue du nourrisson ?","a":"<ul><li>Ne pas pratiquer le <strong>co-sleeping</strong> (partage du lit parental).</li><li>Ne pas <strong>surcouvrir l'enfant</strong> (préférer une turbulette ou une gigoteuse).</li><li>Proscrire l'utilisation de cale-bébé, cale-tête, boudins, cocoon ou réducteurs de lit.</li><li>Ne pas utiliser de lits à parois pleines.</li><li>Proscrire le <strong>tabagisme familial</strong>.</li></ul>"},{"i":"562d65077b74","n":345,"o":"345-8","u":"Prise en charge","t":"Connaître les mesures préventives du malaise grave et de la mort inattendue du nourrisson","q":"Quelles sont les conditions de l'environnement de sommeil à recommander pour prévenir la mort inattendue du nourrisson ?","a":"<ul><li>Le <strong>lit du nourrisson doit être dans la même pièce que les parents</strong> pendant les premiers mois.</li><li>Le lit doit être <strong>vide</strong> : sans oreiller, ni couette, ni couverture.</li><li>Le lit doit être un <strong>berceau rigide</strong> avec un <strong>matelas ferme et à plat</strong>, avec seulement un drap-housse.</li><li>La température de la chambre doit être maintenue entre <strong>18 et 20 °C</strong>.</li></ul>"},{"i":"eb346d5d033e","n":345,"o":"345-8","u":"Prise en charge","t":"Connaître les mesures préventives du malaise grave et de la mort inattendue du nourrisson","q":"Quelle est la principale mesure préventive à conseiller concernant le couchage pour réduire le risque de mort inattendue du nourrisson (MIN) ?","a":"<p>La principale mesure est le <strong>couchage en décubitus dorsal</strong>, qui a permis de réduire significativement les décès par mort subite du nourrisson.</p>"}]};